Rules.InvariantScript:
// ============================================================
// scr_Registration.OnVisible — PRODUCTION VERSION
// Purpose: initialise registration form state and reset all fields
// ============================================================

// ------------------------------------------------------------
// 1. FORM STATE — reset every visit
// ------------------------------------------------------------
Set(varRegFullName, "");
Set(varRegEmail, "");
Set(varRegPhone, "");
Set(varRegDirectorate, "");
Set(varRegProgramme, "");
Set(varRegRole, "");
Set(varRegPassword, "");
Set(varRegConfirmPassword, "");
Set(varRegFormIsValid, false);
Set(varRegPasswordMismatch, false);
Set(varRegEmailExists, false);
Set(varRegSubmitSuccess, false);
Set(varRegErrorMessage, "");
Set(varRegPasswordStrength, "");
Set(varRegAcceptTerms, false);
Set(varRegShowPassword, false);
Set(varRegShowConfirmPassword, false);

// ------------------------------------------------------------
// 2. RESET FORM CONTROLS
// ------------------------------------------------------------
Reset(txt_RegFullName);
Reset(cmb_RegEmail);
Reset(txt_RegPhone);
Reset(drp_RegDirectorate);
Reset(drp_RegProgramme);
Reset(drp_RegRole);
Reset(txt_RegPassword);
Reset(txt_RegConfirmPassword);
Reset(chk_RegAcceptTerms);

// ============================================================
// END OF scr_Registration.OnVisible
// ============================================================

Set(varRegEmail, cmb_RegEmail.Selected.UserPrincipalName);
            Set(varRegEmailExists, CountRows(Filter(APP_Users, UserAccount.Email = cmb_RegEmail.Selected.UserPrincipalName)) > 0);
            Set(varRegFormIsValid, false)

Set(varRegConfirmPassword, txt_RegConfirmPassword.Text);
Set(varRegPasswordMismatch, varRegPassword <> txt_RegConfirmPassword.Text);
Set(varRegFormIsValid, false)

// ============================================================
// RegSubmit_btn.OnSelect — FINAL WORKING VERSION
// ============================================================

// ------------------------------------------------------------
// 1. RESET ERROR STATE
// ------------------------------------------------------------
Set(varRegErrorMessage, "");
Set(varRegSubmitSuccess, false);

// ------------------------------------------------------------
// 2. FIELD VALIDATION
// ------------------------------------------------------------
If(

    IsBlank(varRegEmail),
    Set(varRegErrorMessage, "Please select a user."),

    CountRows(Filter(APP_Users, UserAccount.Email = cmb_RegEmail.Selected.UserPrincipalName)) > 0,
    Set(varRegErrorMessage, "This user already exists in the system."), 

    IsBlank(varRegRole),
    Set(varRegErrorMessage, "System Role is required."),

    IsBlank(varRegDirectorate),
    Set(varRegErrorMessage, "Directorate is required."),

    IsBlank(varRegProgramme),
    Set(varRegErrorMessage, "Programme is required."),

    IsBlank(varRegPassword),
    Set(varRegErrorMessage, "Password is required."),

    Len(varRegPassword) < 8,
    Set(varRegErrorMessage, "Password must be at least 8 characters."),

    IsBlank(varRegConfirmPassword),
    Set(varRegErrorMessage, "Please confirm the password."),

    varRegPassword <> varRegConfirmPassword,
    Set(varRegErrorMessage, "Passwords do not match."),

    !varRegAcceptTerms,
    Set(varRegErrorMessage, "You must accept the terms of use."),

    // ------------------------------------------------------------
    // 3. ALL VALIDATIONS PASSED — SUBMIT
    // ------------------------------------------------------------
    // ------------------------------------------------------------
    // 3. ALL VALIDATIONS PASSED — SUBMIT
    // ------------------------------------------------------------
    With(
        {
        newUser: Patch(
            APP_Users,
            Defaults(APP_Users),
            {
                Title: varRegFullName,
                UserAccount: {
                    Claims: "i:0#.f|membership|" & Lower(varRegEmail),
                    Department: "Public Works and Roads",
                    DisplayName: varRegFullName,
                    Email: Lower(cmb_RegEmail.Selected.Mail),
                    JobTitle: cmb_RegEmail.Selected.JobTitle,
                    Picture: ""
                },
                Role: {Value: varRegRole},
                Programme: {
                    Id: drp_RegProgramme.Selected.ID,
                    Value: drp_RegProgramme.Selected.Title
                },
                Directorate: {
                    Id: drp_RegDirectorate.Selected.ID,
                    Value: drp_RegDirectorate.Selected.DirectorateID
                }
            }
        )
    },
    Patch(
        APP_Users,
        newUser,
        {'Active ': true}
    )
);

    // ------------------------------------------------------------
    // 4. SUCCESS — reset form
    // ------------------------------------------------------------
    Set(varRegSubmitSuccess, true);
    Set(varRegErrorMessage, "");
    Set(varRegFullName, "");
    Set(varRegEmail, "");
    Set(varRegPhone, "");
    Set(varRegRole, "");
    Set(varRegDirectorate, "");
    Set(varRegProgramme, "");
    Set(varRegPassword, "");
    Set(varRegConfirmPassword, "");
    Set(varRegAcceptTerms, false);
    Set(varRegPasswordMismatch, false);
    Set(varRegEmailExists, false);
    Set(varRegPasswordStrength, "");
    Reset(txt_RegFullName);
    Reset(cmb_RegEmail);
    Reset(txt_RegPhone);
    Reset(drp_RegRole);
    Reset(drp_RegDirectorate);
    Reset(drp_RegProgramme);
    Reset(txt_RegPassword);
    Reset(txt_RegConfirmPassword);
    Reset(chk_RegAcceptTerms)
)
